import styled from "styled-components";
import React, {useRef, useState, useEffect} from "react";
import classNames from "classnames";
import "../../styles/WordButton.css";

export const WordButton = ({
	backgroundColor = null,
	primary = false,
	label,
	size = "medium",
}) => {
	const [isActive, setIsActive] = useState(false);
	const toggle = () => {
		setIsActive(!isActive);
	};
	const mode = primary ? "word-button--primary" : "word-button--secondary";
	return (
		<button
			type="button"
			// className={
			// 	isActive
			// 		? `${"word-button"} ${"word-button secondary"}`
			// 		: `${"word-button"} ${"word-button primary"}`
			// }
			className={
				isActive
					? ["word-button", "word-button--primary"].join(" ")
					: ["word-button", "word-button--secondary"].join(" ")
			}
			onClick={() => {
				console.log(label);
				toggle();
				console.log(isActive);
			}}
		>
			{label}
		</button>
	);
};

export default WordButton;
